layui.use(['form', 'table', 'upload'], function () {
    var upload = layui.upload;
    var table  = layui.table;
    var layer  = layui.layer;

    // ⚠️ 必须放在 done 回调中：LayUI 每次渲染表格都重建 toolbar DOM
    function uploadRender() {
        upload.render({
            elem: '#xxxImport',
