            exts: 'xls|xlsx',
            size: 2048,
            url: baseUrl + 'import',
            data: { /* 附带参数如 bdUid: bdUid */ },
            before: function () { layer.load(); },
            done: function (res) {
                layer.closeAll('loading');
                if (res.code === 200) { layer.msg('导入成功', {icon: 1}); currTable.reload(); }
                else { layer.msg(res.msg || '导入失败', {icon: 5}); }
            },
            error: function () { layer.closeAll('loading'); layer.msg('上传出错', {icon: 2}); }
        });
    }

    // 导出按钮：委托事件 + 确认弹窗
    $(document).on('click', '#xxxExport', function () {
        layer.confirm('确定要导出当前筛选条件下的数据吗？', {icon: 3, title: '提示', btn: ['确定', '取消']},
            function (index) {
                layer.close(index);
                var where = currTable.config.where || {};
                var params = [];
                // 拼接过滤参数
                if (where.name) params.push('name=' + encodeURIComponent(where.name));
                window.location.href = baseUrl + 'export' + (params.length ? '?' + params.join('&') : '');
            });
    });

    var currTable = table.render({
        elem: '#tableId',
        url: baseUrl + 'list',
        toolbar: '#toolbarDemo',
        // ...其他配置...
        done: function () {
            uploadRender(); // ← 每次渲染后重新绑定 upload
        }
    });
});
